#!/bin/bash
# Exercise the setup.sql rules against a local Postgres that mimics Supabase's roles and auth helpers.
D=/var/tmp/afcpg; P="psql -h $D -p 5433 -U postgres -d sb -tA -q"
A=11111111-1111-1111-1111-111111111111   # anonymous player A
B=22222222-2222-2222-2222-222222222222   # anonymous player B
O=99999999-9999-9999-9999-999999999999   # the owner (support@afconcity.com)
pass=0; fail=0
as() { # as <role> <claims-json> <sql> : runs in its own transaction as that role; prints result or ERR:<message>
  $P -c "begin; set local role $1; set local request.jwt.claims = '$2'; $3; commit;" 2>&1 | sed -E 's/^psql:[^:]*:[0-9]+: //; s/^ERROR: +/ERR: /' | grep -v -e '^$' -e '^CONTEXT' | tail -1
}
expect() { # expect <name> <pattern> <actual>
  if [[ "$3" =~ $2 ]]; then pass=$((pass+1)); echo "PASS $1"; else fail=$((fail+1)); echo "FAIL $1  (got: $3)"; fi
}
PA="{\"sub\":\"$A\",\"role\":\"authenticated\",\"is_anonymous\":true}"
PB="{\"sub\":\"$B\",\"role\":\"authenticated\",\"is_anonymous\":true}"
PO="{\"sub\":\"$O\",\"role\":\"authenticated\",\"email\":\"Support@AfconCity.com\",\"is_anonymous\":false}"
PX="{\"sub\":\"$B\",\"role\":\"authenticated\",\"email\":\"someone@example.com\",\"is_anonymous\":false}"
$P -c "delete from docs; delete from chat_messages; delete from chat_bans; delete from saves; delete from save_tries; delete from scores; delete from invites; delete from events; delete from bookings; delete from topups; delete from wallets; delete from wallet_ledger; delete from nyota_owned; delete from nicknames;"

expect 'owner is admin' '^t$' "$(as authenticated "$PO" 'select public.is_admin()')"
expect 'anonymous player is not admin' '^f$' "$(as authenticated "$PA" 'select public.is_admin()')"
expect 'other email is not admin' '^f$' "$(as authenticated "$PX" 'select public.is_admin()')"
expect 'owner books a billboard' '^$|COMMIT' "$(as authenticated "$PO" "insert into docs (coll,id,data) values ('billboards','b1','{\"brand\":\"Kibo\"}')")"
expect 'visitor (no login) sees bookings' 'Kibo' "$(as anon '{}' "select data->>'brand' from docs where coll='billboards'")"
expect 'player cannot book a billboard' 'ERR: new row violates row-level security' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('billboards','b2','{}')")"
expect 'player cannot overwrite a booking' '^$|COMMIT|UPDATE 0' "$(as authenticated "$PA" "update docs set data='{\"brand\":\"Hack\"}' where coll='billboards' and id='b1'")"
expect 'booking unchanged after attempt' 'Kibo' "$(as anon '{}' "select data->>'brand' from docs where coll='billboards' and id='b1'")"
expect 'player cannot delete a booking' 'Kibo' "$(as authenticated "$PA" "delete from docs where coll='billboards'"; as anon '{}' "select data->>'brand' from docs where coll='billboards' and id='b1'")"
expect 'visitor cannot write at all' 'ERR: permission denied' "$(as anon '{}' "insert into docs (coll,id,data) values ('billboards','b3','{}')")"
expect 'owner saves the booking contact' '^$|COMMIT' "$(as authenticated "$PO" "insert into docs (coll,id,data) values ('config','ads','{\"contact\":\"support@afconcity.com\"}')")"
expect 'player saves own stats' '^$|COMMIT' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('stats','$A','{\"minutes\":3}')")"
expect 'player updates own stats' '^$|COMMIT' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('stats','$A','{\"minutes\":5}') on conflict (coll,id) do update set data = excluded.data")"
expect 'player cannot write stats for someone else' 'ERR: new row violates' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('stats','$B','{}')")"
expect 'player B cannot read A stats' '^0$' "$(as authenticated "$PB" "select count(*) from docs where coll='stats'")"
expect 'owner reads all stats' '^1$' "$(as authenticated "$PO" "select count(*) from docs where coll='stats'")"
expect 'player sends feedback' '^$|COMMIT' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('feedback/$A/items','f1','{\"text\":\"great\"}')")"
expect 'player cannot post feedback as someone else' 'ERR: new row violates' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('feedback/$B/items','f2','{}')")"
expect 'big player rows refused' 'ERR: new row violates' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('feedback/$A/items','f3', jsonb_build_object('t', repeat('x', 9000)))")"
expect 'owner reads feedback' '^1$' "$(as authenticated "$PO" "select count(*) from docs where coll like 'feedback/%'")"
# chat
expect 'player chats' '^$|COMMIT' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('Asha','Mambo Fumba!')")"
expect 'visitor can read recent chat' 'Mambo Fumba!' "$(as anon '{}' "select body from chat_messages")"
expect 'second message within 1.5 s refused' 'Slow down' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('Asha','again')")"
sleep 1.6
expect 'swear words are starred' '\*\*\*' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('Asha','you are a Fucking idiot') returning body")"
sleep 1.6
expect 'innocent words that start the same are kept' 'kumaliza' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('Asha','nataka kumaliza kazi') returning body")"
sleep 1.6
expect 'rude nickname replaced' '^Fan' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('shit','hi') returning nick")"
expect 'cannot chat as someone else' 'ERR: new row violates' "$(as authenticated "$PA" "insert into chat_messages (owner, nick, body) values ('$B','B','fake')")"
expect 'visitor cannot chat' 'ERR: permission denied' "$(as anon '{}' "insert into chat_messages (nick, body) values ('x','y')")"
expect 'over-long messages refused' 'violates check constraint' "$(as authenticated "$PB" "insert into chat_messages (nick, body) values ('B', repeat('a', 91))")"
expect 'player cannot ban' 'ERR: new row violates' "$(as authenticated "$PA" "insert into chat_bans (uid) values ('$B')")"
expect 'owner bans player B' '^$|COMMIT' "$(as authenticated "$PO" "insert into chat_bans (uid, reason) values ('$B','test')")"
expect 'banned player cannot chat' 'cannot chat' "$(as authenticated "$PB" "insert into chat_messages (nick, body) values ('B','hello')")"
expect 'owner switches chat off' '^$|COMMIT' "$(as authenticated "$PO" "insert into docs (coll,id,data) values ('config','chat','{\"chat\":false}')")"
sleep 1.6
expect 'chat off: player refused' 'switched off' "$(as authenticated "$PA" "insert into chat_messages (nick, body) values ('Asha','hello?')")"
expect 'owner turns chat back on' '^$|COMMIT' "$(as authenticated "$PO" "update docs set data='{\"chat\":true}' where coll='config' and id='chat'")"
expect 'player can report' '^$|COMMIT' "$(as authenticated "$PA" "insert into docs (coll,id,data) values ('reports','r1','{\"target\":\"$B\"}')")"
expect 'players cannot read reports of others' '^0$' "$(as authenticated "$PB" "select count(*) from docs where coll='reports'")"
expect 'owner reads reports' '^1$' "$(as authenticated "$PO" "select count(*) from docs where coll='reports'")"
expect 'admins list is not readable' 'ERR: permission denied|^$' "$(as authenticated "$PA" "select email from admins")"
# ---- version 2: teen chat, cloud saves, leaderboards, invites, analytics, bookings ----
sleep 1.6
expect 'teen marked in stats' '^$|COMMIT' "$(as authenticated "$PB" "insert into docs (coll,id,data) values ('stats','$B','{\"about\":{\"age\":\"Under 18\"}}')")"
$P -c "delete from chat_bans;"
expect 'teen cannot type free text' 'quick phrases' "$(as authenticated "$PB" "insert into chat_messages (nick, body) values ('B','hello stranger')")"
sleep 1.6
expect 'teen can send a quick phrase' 'Twende' "$(as authenticated "$PB" "insert into chat_messages (nick, body) values ('B','Twende!') returning body")"
CODE=$(as authenticated "$PA" "select public.save_put(null, '{\"cash\":123}')")
expect 'cloud save gets a 10-letter code' '^[A-HJ-NP-Z2-9]{10}$' "$CODE"
expect 'visitor cannot save' 'ERR' "$(as anon '{}' "select public.save_put(null, '{}')")"
expect 'saves are not readable directly' 'ERR: permission denied|^0$' "$(as authenticated "$PB" "select count(*) from saves")"
expect 'owner of the code updates it' "$CODE" "$(as authenticated "$PA" "select public.save_put('$CODE', '{\"cash\":456}')")"
expect 'wrong code is refused' 'No save has that code' "$(as authenticated "$PB" "select public.save_load('AAAAAAAAAA')")"
expect 'another phone loads with the code (dashes and case ignored)' '456' "$(as authenticated "$PB" "select public.save_load('$(echo ${CODE:0:5} | tr A-Z a-z)-${CODE:5}')->'data'->>'cash'")"
expect 'the old phone can no longer overwrite it' 'moved to another device' "$(as authenticated "$PA" "select public.save_put('$CODE', '{\"cash\":1}')")"
expect 'the new phone continues the save' "$CODE" "$(as authenticated "$PB" "select public.save_put('$CODE', '{\"cash\":789}')")"
expect 'player posts a score' '^$|COMMIT' "$(as authenticated "$PA" "insert into scores (nick, worth, stamps, week, week_stamps) values ('Asha', 250000, 3, '2026-W42', 3)")"
expect 'anyone reads the leaderboard' 'Asha' "$(as anon '{}' "select nick from scores order by worth desc limit 1")"
expect 'impossible scores refused' 'violates check constraint' "$(as authenticated "$PB" "insert into scores (nick, worth) values ('B', 999999999999)")"
expect 'cannot post a score for someone else' 'ERR: new row violates' "$(as authenticated "$PB" "insert into scores (uid, nick) values ('$A', 'fake')")"
expect 'rude leaderboard names are replaced' '^Fan$' "$(as authenticated "$PB" "insert into scores (nick) values ('shit') returning nick")"
expect 'players cannot set their own invite code' '^$|Too often' "$(as authenticated "$PA" "update scores set ref='aaaaaa' where uid='$A' returning coalesce(ref,'')" | grep -v UPDATE)"
expect 'invite code still empty' '^$' "$($P -c "select coalesce(ref,'') from scores where uid='$A'")"
REF=$(as authenticated "$PA" "select public.my_ref()")
expect 'a player gets an invite code' '^[a-z0-9]{6}$' "$REF"
expect 'the invite code is stable' "$REF" "$(as authenticated "$PA" "select public.my_ref()")"
expect 'you cannot invite yourself' '^f$' "$(as authenticated "$PA" "select public.invite_accept('$REF')")"
expect 'a friend accepts the invite' '^t$' "$(as authenticated "$PB" "select public.invite_accept('$REF')")"
expect 'only once' '^f$' "$(as authenticated "$PB" "select public.invite_accept('$REF')")"
expect 'no reward in the first minutes' '^f$' "$(as authenticated "$PB" "select public.invite_qualify()")"
$P -c "update invites set created_at = now() - interval '10 minutes';"
expect 'the friend earns their reward once they get going' '^t$' "$(as authenticated "$PB" "select public.invite_qualify()")"
expect 'and only once' '^f$' "$(as authenticated "$PB" "select public.invite_qualify()")"
expect 'the inviter collects one reward' '^1$' "$(as authenticated "$PA" "select public.invite_collect()")"
expect 'and cannot collect it twice' '^0$' "$(as authenticated "$PA" "select public.invite_collect()")"
expect 'player logs an event' '^$|COMMIT' "$(as authenticated "$PA" "insert into events (sid, name, props) values ('s123','session_start','{\"src\":\"whatsapp\",\"dev\":\"touch\"}')")"
expect 'odd event names refused' 'violates check constraint' "$(as authenticated "$PA" "insert into events (sid, name) values ('s123','DROP TABLE')")"
expect 'players cannot read analytics' '^0$' "$(as authenticated "$PB" "select count(*) from events")"
expect 'players cannot run the summary' 'Owners only' "$(as authenticated "$PB" "select public.analytics_summary(14)")"
expect 'owner sees the summary' 'whatsapp' "$(as authenticated "$PO" "select public.analytics_summary(14)::text")"
expect 'players cannot create bookings' 'ERR' "$(as authenticated "$PA" "insert into bookings (slot, months, start_date, brand, headline, contact_name, contact_email, amount, currency) values ('b1',1,current_date,'X','Y','Z','z@x.co',1,'TZS')")"
expect 'players cannot read bookings' '^0$' "$(as authenticated "$PA" "select count(*) from bookings")"
$P -c "insert into bookings (slot, months, start_date, brand, headline, contact_name, contact_email, amount, currency, status) values ('b2',1,current_date,'Kibo','KIBO','Ann','ann@kibo.co',150000,'TZS','paid');"
expect 'owner reads paid bookings' '^1$' "$(as authenticated "$PO" "select count(*) from bookings where status='paid'")"
expect 'owner approves a booking' '^$|COMMIT|UPDATE 1' "$(as authenticated "$PO" "update bookings set status='approved' where slot='b2'")"
expect 'clean-up runs' '^$|afc_cleanup' "$($P -c "select public.afc_cleanup();" 2>&1 | tail -1)"
# Nyota: premium coins
expect 'anyone can see the Nyota prices' '^6$' "$(as anon '{}' "select count(*) from nyota_items where active")"
expect 'a new player has no Nyota' '"nyota": 0' "$(as authenticated "$PA" "select public.nyota_state()::text")"
expect 'players cannot give themselves Nyota' 'ERR: permission denied' "$(as authenticated "$PA" "insert into wallets (uid, nyota) values ('$A', 99999)")"
expect 'players cannot change their balance' 'ERR: permission denied' "$(as authenticated "$PA" "update wallets set nyota = 99999")"
expect 'players cannot call the credit function' 'ERR: permission denied' "$(as authenticated "$PA" "select public.nyota_credit(gen_random_uuid())")"
expect 'buying with no Nyota is refused' 'Not enough Nyota' "$(as authenticated "$PA" "select public.nyota_buy('tag_gold')")"
TU=$($P -c "insert into topups (uid, pack, nyota, amount, currency) values ('$A', 'p550', 550, 10000, 'TZS') returning id" | head -1)
expect 'a paid top-up is credited' '^550$' "$($P -c "select public.nyota_credit('$TU')" | head -1)"
expect 'and only once, however often Bachs calls' '^0$' "$($P -c "select public.nyota_credit('$TU')" | head -1)"
expect 'the balance shows 550' '"nyota": 550' "$(as authenticated "$PA" "select public.nyota_state()::text")"
expect 'player B cannot see A wallet' '^0$' "$(as authenticated "$PB" "select count(*) from wallets")"
expect 'buy the golden name tag (400)' '"nyota": 150' "$(as authenticated "$PA" "select public.nyota_buy('tag_gold')::text")"
expect 'it shows as owned' 'tag_gold' "$(as authenticated "$PA" "select public.nyota_state()::text")"
expect 'cannot buy it twice' 'already own' "$(as authenticated "$PA" "select public.nyota_buy('tag_gold')")"
expect 'a timed pass can be bought' '"nyota": 0' "$(as authenticated "$PA" "select public.nyota_buy('pass_collect')::text")"
expect 'the ledger records every change' '^3$' "$(as authenticated "$PA" "select count(*) from wallet_ledger")"
expect 'unknown items refused' 'not for sale' "$(as authenticated "$PA" "select public.nyota_buy('free_money')")"
$P -c "select public.nyota_credit(id) from (select id from (insert into topups (uid, pack, nyota, amount) values ('$A', 'p100', 100, 2000) returning id) x) y;" >/dev/null 2>&1 || $P -c "with x as (insert into topups (uid, pack, nyota, amount) values ('$A', 'p100', 100, 2000) returning id) select public.nyota_credit(id) from x;" >/dev/null
expect 'save loaded on another device: Nyota move with it' '"nyota": 100' "$(as authenticated "$PA" "select public.save_put(null, '{\"v\":4}')" > /tmp/afc_code; as authenticated "$PB" "select (public.save_load('$(cat /tmp/afc_code)'))::text" >/dev/null; as authenticated "$PB" "select public.nyota_state()::text")"
expect 'items move too' 'tag_gold' "$(as authenticated "$PB" "select public.nyota_state()::text")"
expect 'the old device keeps nothing' '"nyota": 0' "$(as authenticated "$PA" "select public.nyota_state()::text")"
TR=$($P -c "select ref from wallet_ledger where reason = 'topup' and delta = 100 limit 1" | head -1)
expect 'players cannot refund' 'Owners only' "$(as authenticated "$PB" "select public.nyota_refund('$TR')")"
expect 'owner refunds a top-up: its Nyota are taken back' '^100$' "$(as authenticated "$PO" "select public.nyota_refund('$TR')")"
expect 'balance after the refund' '"nyota": 0' "$(as authenticated "$PB" "select public.nyota_state()::text")"
# unique fan names
C=33333333-3333-3333-3333-333333333333; E=44444444-4444-4444-4444-444444444444
PC="{\"sub\":\"$C\",\"role\":\"authenticated\",\"is_anonymous\":true}"
PE="{\"sub\":\"$E\",\"role\":\"authenticated\",\"is_anonymous\":true}"
expect 'a free name is free' '^free$' "$(as anon '{}' "select public.nick_status('Zuri K')")"
expect 'lock in a name' '"status": "mine"' "$(as authenticated "$PC" "select public.nick_claim('Zuri K')::text")"
expect 'it reads as mine' '^mine$' "$(as authenticated "$PC" "select public.nick_status('zuri_k')")"
expect 'others see it as taken (spacing and case do not matter)' '^taken$' "$(as authenticated "$PE" "select public.nick_status('ZURIK')")"
expect 'nobody else can lock it in' 'locked in that name' "$(as authenticated "$PE" "select public.nick_claim('zuri.k')")"
expect 'reserved names refused' 'reserved' "$(as authenticated "$PE" "select public.nick_claim('Admin')")"
expect 'default Fan names cannot be locked' 'reserved' "$(as authenticated "$PE" "select public.nick_claim('Fan 27')")"
expect 'rude names refused' 'friendlier' "$(as authenticated "$PE" "select public.nick_claim('shit lord')")"
expect 'ordinary names that contain a rude word are fine' '^free$' "$(as authenticated "$PE" "select public.nick_status('Dickson')")"
expect 'too short or odd names refused' '^bad$' "$(as authenticated "$PE" "select public.nick_status('<a>')")"
expect 'players cannot write names directly' 'ERR: permission denied' "$(as authenticated "$PE" "insert into nicknames (key, nick, uid) values ('hack','hack','$E')")"
expect 'changing case of your own name is fine' '"nick": "ZURI K"' "$(as authenticated "$PC" "select public.nick_claim('ZURI K')::text")"
expect 'a new name only once a day' 'once a day' "$(as authenticated "$PC" "select public.nick_claim('Zuri Two')")"
expect 'the leaderboard will not show a locked name for someone else' '^Fan$' "$(as authenticated "$PE" "insert into scores (nick) values ('Zuri K') returning nick")"
sleep 1.6
expect 'chat will not show a locked name for someone else' '^Fan$' "$(as authenticated "$PE" "insert into chat_messages (nick, body) values ('zuri k','hi') returning nick")"
expect 'the owner of the name keeps it on the board' '^ZURI K$' "$(as authenticated "$PC" "insert into scores (nick) values ('ZURI K') returning nick")"
expect 'a locked name moves with the save code' '^ZURI K$' "$(as authenticated "$PC" "select public.save_put(null, '{\"v\":5}')" > /tmp/afc_code2; as authenticated "$PE" "select (public.save_load('$(cat /tmp/afc_code2)'))::text" >/dev/null; as authenticated "$PE" "select public.nick_mine()")"
expect 'invite counts for my panel' '"joined": 0' "$(as authenticated "$PE" "select public.my_invites()::text")"
expect 'visitors cannot claim' 'ERR: permission denied' "$(as anon '{}' "select public.nick_claim('Ghost')")"
echo "$pass passed, $fail failed"
